-- WeChat Data Hub PostgreSQL 17 reference DDL, v1.0
-- DESIGN REFERENCE ONLY: generate final migrations with Alembic; do not run blindly on production.
-- UUID generated by pgcrypto's gen_random_uuid() available in supported PostgreSQL.
CREATE EXTENSION IF NOT EXISTS citext;
-- The application MUST also enforce cross-table workspace ownership for every write/query.

CREATE TABLE workspaces (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    username citext UNIQUE NOT NULL,
    password_hash text NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);
-- App/migration must CREATE EXTENSION IF NOT EXISTS citext before users.

CREATE TABLE memberships (
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    user_id uuid NOT NULL REFERENCES users(id),
    role text NOT NULL CHECK (role IN ('admin', 'reviewer', 'reader')),
    PRIMARY KEY (workspace_id, user_id)
);

CREATE TABLE wechat_accounts (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    account_ref text NOT NULL,
    display_name text,
    status text NOT NULL DEFAULT 'unverified',
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (workspace_id, account_ref)
);

CREATE TABLE source_devices (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    account_id uuid REFERENCES wechat_accounts(id),
    device_ref text NOT NULL,
    platform text NOT NULL CHECK (platform IN ('ios','macos','windows','other')),
    os_version text,
    wechat_version text,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (workspace_id, device_ref)
);

CREATE TABLE source_blobs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    sha256 char(64) NOT NULL,
    byte_size bigint NOT NULL CHECK (byte_size >= 0),
    cas_key text NOT NULL,
    storage_state text NOT NULL DEFAULT 'available',
    stored_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (workspace_id, sha256)
);

CREATE TABLE ingest_batches (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    account_id uuid REFERENCES wechat_accounts(id),
    device_id uuid REFERENCES source_devices(id),
    main_blob_id uuid NOT NULL REFERENCES source_blobs(id),
    adapter_id text NOT NULL,
    adapter_version text NOT NULL,
    manifest jsonb NOT NULL,
    original_timezone text,
    batch_status text NOT NULL DEFAULT 'uploaded',
    started_at timestamptz,
    finished_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (workspace_id, main_blob_id, adapter_id, adapter_version)
);

CREATE TABLE raw_records (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    batch_id uuid NOT NULL REFERENCES ingest_batches(id),
    source_record_locator text NOT NULL,
    source_primary_key text,
    raw_sha256 char(64) NOT NULL,
    raw_payload jsonb,
    raw_blob_id uuid REFERENCES source_blobs(id),
    parse_status text NOT NULL DEFAULT 'pending',
    parse_errors jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (batch_id, source_record_locator)
);

CREATE TABLE contacts (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    account_id uuid NOT NULL REFERENCES wechat_accounts(id),
    native_contact_id text,
    display_name text,
    identity_status text NOT NULL DEFAULT 'unverified',
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_native_contacts ON contacts(account_id, native_contact_id)
    WHERE native_contact_id IS NOT NULL;

CREATE TABLE contact_aliases (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    contact_id uuid NOT NULL REFERENCES contacts(id),
    alias text NOT NULL,
    alias_type text NOT NULL,
    source_raw_id uuid REFERENCES raw_records(id),
    seen_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE conversations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    account_id uuid NOT NULL REFERENCES wechat_accounts(id),
    native_conversation_id text,
    kind text NOT NULL CHECK (kind IN ('private','group','official','unknown')),
    title text,
    privacy_scope text NOT NULL DEFAULT 'private'
      CHECK (privacy_scope IN ('private','business_approved')),
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_native_conversations
    ON conversations(account_id, native_conversation_id)
    WHERE native_conversation_id IS NOT NULL;

CREATE TABLE conversation_memberships (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id uuid NOT NULL REFERENCES conversations(id),
    contact_id uuid NOT NULL REFERENCES contacts(id),
    valid_from timestamptz,
    valid_to timestamptz,
    source_raw_id uuid REFERENCES raw_records(id),
    CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);

CREATE TABLE messages (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    account_id uuid NOT NULL REFERENCES wechat_accounts(id),
    conversation_id uuid NOT NULL REFERENCES conversations(id),
    sender_contact_id uuid REFERENCES contacts(id),
    sent_at_utc timestamptz,
    original_time_text text,
    original_time_precision text NOT NULL DEFAULT 'unknown'
      CHECK (original_time_precision IN ('second','millisecond','minute','day','unknown')),
    message_type text NOT NULL,
    original_type_code text,
    body_text text,
    body_format text NOT NULL DEFAULT 'text/plain',
    reply_to_message_id uuid REFERENCES messages(id),
    unresolved_reply_key text,
    native_server_id text,
    native_id_verified boolean NOT NULL DEFAULT false,
    normalization_version text NOT NULL,
    merge_status text NOT NULL DEFAULT 'single_source'
      CHECK (merge_status IN ('verified','candidate','conflicted','single_source')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_messages_timeline ON messages(conversation_id, sent_at_utc, id);
CREATE INDEX ix_messages_account_sender ON messages(account_id, sender_contact_id, sent_at_utc);
-- Strong native-server-id uniqueness MUST be carefully scoped by a verified adapter namespace.
-- Do NOT globally UNIQUE(native_server_id) before confirming source semantics.

CREATE TABLE message_observations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    message_id uuid NOT NULL REFERENCES messages(id),
    raw_record_id uuid NOT NULL REFERENCES raw_records(id),
    device_id uuid REFERENCES source_devices(id),
    source_message_id text,
    observed_fields jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (raw_record_id)
);
CREATE INDEX ix_msg_observations_message ON message_observations(message_id);

CREATE TABLE message_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    message_id uuid NOT NULL REFERENCES messages(id),
    source_raw_id uuid REFERENCES raw_records(id),
    event_type text NOT NULL,
    event_time timestamptz,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE attachments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    sha256 char(64),
    blob_id uuid REFERENCES source_blobs(id),
    byte_size bigint,
    mime_type text,
    original_filename text,
    availability text NOT NULL DEFAULT 'missing'
      CHECK (availability IN ('available','missing','quarantined','unsupported')),
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_attachment_content ON attachments(workspace_id, sha256)
    WHERE sha256 IS NOT NULL;

CREATE TABLE message_attachments (
    message_id uuid NOT NULL REFERENCES messages(id),
    attachment_id uuid NOT NULL REFERENCES attachments(id),
    position integer NOT NULL DEFAULT 0,
    source_raw_id uuid REFERENCES raw_records(id),
    original_media_path text,
    PRIMARY KEY (message_id, attachment_id, position)
);

CREATE TABLE jobs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    kind text NOT NULL,
    status text NOT NULL DEFAULT 'queued',
    idempotency_key text,
    payload jsonb NOT NULL DEFAULT '{}'::jsonb,
    attempt_count integer NOT NULL DEFAULT 0,
    lease_until timestamptz,
    next_retry_at timestamptz,
    failure_code text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_jobs_idempotency
    ON jobs(workspace_id, kind, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX ix_jobs_polling ON jobs(status, next_retry_at, lease_until);

CREATE TABLE entity_assertions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    entity_type text NOT NULL,
    payload jsonb NOT NULL,
    extractor_version text NOT NULL,
    review_status text NOT NULL DEFAULT 'pending',
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE evidence_links (
    assertion_id uuid NOT NULL REFERENCES entity_assertions(id),
    message_id uuid NOT NULL REFERENCES messages(id),
    source_span text,
    PRIMARY KEY (assertion_id, message_id)
);

CREATE TABLE approved_entities (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    assertion_id uuid NOT NULL UNIQUE REFERENCES entity_assertions(id),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    approved_payload jsonb NOT NULL,
    approved_by uuid NOT NULL REFERENCES users(id),
    approved_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE review_tasks (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    review_type text NOT NULL,
    object_ref uuid NOT NULL,
    review_status text NOT NULL DEFAULT 'pending',
    decision jsonb,
    reviewer_id uuid REFERENCES users(id),
    reviewed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE sync_outbox (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    approved_entity_id uuid NOT NULL REFERENCES approved_entities(id),
    target_system text NOT NULL,
    target_model text NOT NULL,
    idempotency_key text NOT NULL UNIQUE,
    request_fingerprint char(64) NOT NULL,
    status text NOT NULL DEFAULT 'pending_approval',
    remote_id text,
    attempts integer NOT NULL DEFAULT 0,
    last_error_code text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE audit_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id uuid NOT NULL REFERENCES workspaces(id),
    actor_id uuid REFERENCES users(id),
    event_type text NOT NULL,
    object_type text,
    object_id uuid,
    result text NOT NULL,
    request_id text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_audit_created ON audit_events(workspace_id, created_at DESC);

-- Integrity checks that must be implemented by tests (cross-table ownership, provenance):
-- 1) messages.account.workspace_id == messages.workspace_id
-- 2) messages.conversation.workspace_id == messages.workspace_id
-- 3) message_observations.raw_record.workspace_id == messages.workspace_id
-- 4) an approved entity has evidence_links to at least one valid message
-- 5) all referenced blobs exist, their on-disk SHA256 matches source_blobs.sha256
-- 6) no role can read/write a workspace without membership authorization
